const fs = require('fs');
const https = require('https');

const token = fs.readFileSync('/governance/.discord-token', 'utf8').trim();
const statePath = '/governance/shared/.n8n-law1-state.json';
const registryPath = '/governance/operations/PROJECT-REGISTRY.md';
const channelId = '1476794551250194443';

let lastId = '0';
try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  lastId = state.lastMessageId || '0';
} catch(e) {}

const messages = await new Promise((resolve) => {
  const req = https.request({
    hostname: 'discord.com',
    path: `/api/v10/channels/${channelId}/messages?limit=10`,
    method: 'GET',
    headers: { 'Authorization': `Bot ${token}` }
  }, (res) => {
    let data = ''; res.on('data', c => data += c);
    res.on('end', () => { try { resolve(JSON.parse(data)); } catch(e) { resolve([]); } });
  });
  req.on('error', () => resolve([]));
  req.end();
});

if (!Array.isArray(messages) || messages.length === 0) {
  return [{ json: { violations: 0, processed: 0 } }];
}

const newMessages = messages.filter(m => m.id > lastId).reverse();
if (newMessages.length === 0) {
  return [{ json: { violations: 0, processed: 0 } }];
}

let registryContent = '';
try { registryContent = fs.readFileSync(registryPath, 'utf8'); } catch(e) {
  return [{ json: { error: 'Cannot read PROJECT-REGISTRY.md' } }];
}

const projIdPattern = /PROJ-[A-Z0-9]+-?[A-Z0-9]*/g;
const registeredIds = new Set(registryContent.match(projIdPattern) || []);
const violations = [];

for (const msg of newMessages) {
  const content = msg.content || '';
  const author = msg.author?.username || 'unknown';
  const mentioned = content.match(/PROJ-[A-Z0-9]+-?[A-Z0-9]*/g);

  if (!mentioned || mentioned.length === 0) {
    violations.push({ type: 'NO_PROJECT_ID', author, content: content.substring(0, 200), timestamp: msg.timestamp });
  } else {
    for (const projId of mentioned) {
      if (!registeredIds.has(projId)) {
        violations.push({ type: 'UNREGISTERED', projId, author, content: content.substring(0, 200), timestamp: msg.timestamp });
      }
    }
  }
}

// Send alerts for violations
const severityAlerts = '1476794637762039808';
const humanOversight = '1476794543897837662';

for (const v of violations) {
  let message = '';
  if (v.type === 'NO_PROJECT_ID') {
    message = `\u{1F6A8} **LAW 1 VIOLATION \u2014 CRITICAL**\n\n**Type:** Task dispatched without Project ID\n**Author:** ${v.author}\n**Time:** ${v.timestamp}\n**Content:** \`${v.content}\`\n\n> _No Project ID, No Work Allowed_ \u2014 CORE-CHARTER Law 1\n> This work product is considered **invalid**.`;
  } else {
    message = `\u{1F6A8} **LAW 1 VIOLATION \u2014 CRITICAL**\n\n**Type:** Unregistered Project ID\n**Project ID:** ${v.projId}\n**Author:** ${v.author}\n**Time:** ${v.timestamp}\n\n> Project \`${v.projId}\` not in PROJECT-REGISTRY.md.`;
  }

  for (const ch of [severityAlerts, humanOversight]) {
    const body = JSON.stringify({ content: message });
    await new Promise((resolve) => {
      const req = https.request({
        hostname: 'discord.com', path: `/api/v10/channels/${ch}/messages`, method: 'POST',
        headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
      }, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => resolve(d)); });
      req.write(body); req.end();
    });
  }
}

const newestId = newMessages[newMessages.length - 1]?.id || lastId;
try { fs.writeFileSync(statePath, JSON.stringify({ lastMessageId: newestId, updatedAt: new Date().toISOString() })); } catch(e) {}

return [{ json: { violations: violations.length, processed: newMessages.length } }];
